/**
 * Barangay Sto. Tomas — Official Document Printer
 * Sto. Tomas, Magarao, Camarines Sur
 */

const BARANGAY = {
  name:     'BARANGAY STO. TOMAS',
  municipality: 'Municipality of Magarao',
  province: 'Province of Camarines Sur',
  region:   'Region V (Bicol Region)',
  address:  'Sto. Tomas, Magarao, Camarines Sur',
  seal:     "data:image/png;base64,",
};

const DOC_TITLES = {
  // From admin DocumentPage title prop
  'Barangay Clearance':      'BARANGAY CLEARANCE',
  'Certificate of Indigency':'CERTIFICATE OF INDIGENCY',
  'Certificate of Residency':'CERTIFICATE OF RESIDENCY',
  'Business Permit':         'BARANGAY BUSINESS PERMIT',
  // From resident MyRequests doc_type
  'Cert. of Indigency':      'CERTIFICATE OF INDIGENCY',
  'Cert. of Residency':      'CERTIFICATE OF RESIDENCY',
  // From docKey fallback
  clearance:  'BARANGAY CLEARANCE',
  indigency:  'CERTIFICATE OF INDIGENCY',
  residency:  'CERTIFICATE OF RESIDENCY',
  permits:    'BARANGAY BUSINESS PERMIT',
};

const DOC_BODY = {
  'Barangay Clearance': (r) => `
    <p>TO WHOM IT MAY CONCERN:</p>
    <p>This is to certify that <strong>${r.full_name}</strong>, of legal age, a resident of
    <strong>${BARANGAY.address}</strong>, is personally known to this office and is of good moral
    character and has no derogatory record on file in this Barangay.</p>
    <p>This certification is issued upon the request of the above-named person for whatever
    legal purpose it may serve.</p>`,

  'Certificate of Indigency': (r) => `
    <p>TO WHOM IT MAY CONCERN:</p>
    <p>This is to certify that <strong>${r.full_name}</strong>, of legal age, a bonafide resident of
    <strong>${BARANGAY.address}</strong>, belongs to an indigent family in this Barangay and is
    not financially capable of shouldering his/her needs.</p>
    <p>This certification is issued upon the request of the above-named person for whatever
    legal purpose it may serve.</p>`,

  'Certificate of Residency': (r) => `
    <p>TO WHOM IT MAY CONCERN:</p>
    <p>This is to certify that <strong>${r.full_name}</strong>, of legal age, is a bonafide resident of
    <strong>${BARANGAY.address}</strong> as verified from the records of this Barangay.</p>
    <p>This certification is issued upon the request of the above-named person for whatever
    legal purpose it may serve.</p>`,

  'Business Permit': (r) => `
    <p>TO WHOM IT MAY CONCERN:</p>
    <p>This is to certify that <strong>${r.full_name}</strong>, owner/operator of
    <strong>${r.business_name || r.full_name + '\'s Business'}</strong>, located at
    <strong>${BARANGAY.address}</strong>, has been granted permission to operate in accordance
    with existing rules and regulations of Barangay Sto. Tomas.</p>
    <p>This permit is being issued subject to existing rules and regulations provided however,
    that the necessary fees are paid to the Treasurer of the Barangay as assessed.</p>`,
};

// Aliases so short names also work
DOC_BODY['Cert. of Indigency'] = DOC_BODY['Certificate of Indigency'];
DOC_BODY['Cert. of Residency'] = DOC_BODY['Certificate of Residency'];

function getBody(docType, r) {
  const fn = DOC_BODY[docType]
    || DOC_BODY[DOC_TITLES[docType]]
    || DOC_BODY['Barangay Clearance'];
  return fn(r);
}

function formatDate(dateStr) {
  if (!dateStr) return '_______________';
  return new Date(dateStr).toLocaleDateString('en-PH', {
    year: 'numeric', month: 'long', day: 'numeric'
  });
}

export function printDocument(row, docType) {
  const title    = DOC_TITLES[docType] || DOC_TITLES['Barangay Clearance'];
  const body     = getBody(docType, row);
  const issued   = formatDate(row.date_issued || row.updated_at || new Date().toISOString());
  const orNum    = row.or_number || '—';
  const issuedBy = row.issued_by || 'Punong Barangay';

  const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>${title} — ${row.ref_number}</title>
<style>
  * { margin:0; padding:0; box-sizing:border-box; }

  @page { size: letter portrait; margin: 0.7in 0.8in; }

  body {
    font-family: 'Times New Roman', Times, serif;
    font-size: 13pt;
    color: #000;
    background: #fff;
    line-height: 1.6;
  }

  .page {
    max-width: 720px;
    margin: 0 auto;
    padding: 0;
    position: relative;
  }

  /* ── WATERMARK ── */
  .watermark {
    position: fixed;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%) rotate(-30deg);
    opacity: 0.04;
    pointer-events: none;
    z-index: 0;
  }
  .watermark img { width: 480px; height: 480px; }

  /* ── BORDER ── */
  .border-outer {
    border: 4px double #1a3a6b;
    padding: 6px;
    margin-bottom: 0;
  }
  .border-inner {
    border: 1.5px solid #1a3a6b;
    padding: 20px 28px 24px;
    position: relative;
    z-index: 1;
  }

  /* ── HEADER ── */
  .header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 10px;
    padding-bottom: 10px;
    border-bottom: 2px solid #1a3a6b;
  }
  .header-center { text-align: center; flex: 1; }
  .republic {
    font-size: 9.5pt;
    color: #333;
    font-style: italic;
    margin-bottom: 1px;
  }
  .province {
    font-size: 9.5pt;
    color: #333;
    margin-bottom: 1px;
  }
  .municipality {
    font-size: 10pt;
    font-weight: bold;
    color: #1a3a6b;
    margin-bottom: 4px;
  }
  .office-label {
    font-size: 9pt;
    color: #555;
    letter-spacing: 1px;
    text-transform: uppercase;
    margin-bottom: 4px;
  }
  .office-name {
    font-size: 13pt;
    font-weight: bold;
    color: #1a3a6b;
    letter-spacing: 0.5px;
    text-transform: uppercase;
  }
  .seal { width: 90px; height: 90px; object-fit: contain; flex-shrink: 0; border-radius: 0; border: none; background: none; }

  /* ── DOC TITLE ── */
  .doc-title-wrap {
    text-align: center;
    margin: 14px 0 18px;
    padding: 10px 0;
    border-top: 1px solid #c8d4e8;
    border-bottom: 1px solid #c8d4e8;
  }
  .doc-title {
    font-size: 18pt;
    font-weight: bold;
    color: #1a3a6b;
    letter-spacing: 2px;
    text-transform: uppercase;
  }

  /* ── META ROW ── */
  .meta-row {
    display: flex;
    justify-content: space-between;
    font-size: 10pt;
    color: #333;
    margin-bottom: 16px;
    gap: 20px;
  }
  .meta-item { display: flex; flex-direction: column; gap: 2px; }
  .meta-label { font-size: 8pt; text-transform: uppercase; letter-spacing: 0.8px; color: #777; }
  .meta-value { font-weight: bold; color: #1a3a6b; font-family: 'Courier New', monospace; font-size: 10.5pt; }

  /* ── BODY ── */
  .doc-body {
    font-size: 12.5pt;
    line-height: 1.85;
    text-align: justify;
    color: #111;
    margin-bottom: 20px;
  }
  .doc-body p { margin-bottom: 14px; text-indent: 40px; }
  .doc-body p:first-child { text-indent: 0; font-weight: bold; }

  /* ── GIVEN ── */
  .given {
    font-size: 11.5pt;
    margin-bottom: 28px;
    color: #222;
  }

  /* ── SIGNATURE ── */
  .signature-section {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-top: 10px;
    gap: 20px;
  }
  .sig-left { flex: 1; font-size: 10pt; color: #333; }
  .sig-right { text-align: center; min-width: 220px; }
  .sig-name {
    font-size: 13pt;
    font-weight: bold;
    color: #1a3a6b;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    border-bottom: 1.5px solid #1a3a6b;
    padding-bottom: 4px;
    margin-bottom: 3px;
  }
  .sig-title { font-size: 10pt; font-style: italic; color: #444; }

  /* ── OWNER/REQUESTEE ── */
  .requestee-section {
    margin-top: 22px;
    padding-top: 12px;
    border-top: 1px dashed #aaa;
    display: flex;
    justify-content: space-between;
    font-size: 10pt;
  }
  .requestee-box { min-width: 200px; }
  .requestee-name {
    font-weight: bold;
    font-size: 11.5pt;
    border-bottom: 1px solid #000;
    padding-bottom: 2px;
    margin-bottom: 2px;
  }
  .requestee-label { font-size: 9pt; color: #555; }

  /* ── FOOTER ── */
  .doc-footer {
    margin-top: 16px;
    padding-top: 10px;
    border-top: 1px solid #c8d4e8;
    display: flex;
    justify-content: space-between;
    font-size: 9pt;
    color: #777;
    font-style: italic;
  }

  /* ── NOT VALID ── */
  .not-valid {
    text-align: center;
    font-size: 9pt;
    color: #888;
    font-style: italic;
    margin-top: 8px;
  }
</style>
</head>
<body>
<div class="page">

  <!-- Watermark -->
  <div class="watermark"><img src="data:image/png;base64," alt="" /></div>

  <div class="border-outer">
  <div class="border-inner">

    <!-- HEADER -->
    <div class="header">
      <img class="seal" src="data:image/png;base64," alt="Barangay Seal" />
      <div class="header-center">
        <div class="republic">Republic of the Philippines</div>
        <div class="province">Province of Camarines Sur</div>
        <div class="municipality">Municipality of Magarao</div>
        <div class="office-label">Office of the Punong Barangay</div>
        <div class="office-name">Barangay Sto. Tomas</div>
        <div style="font-size:9pt;color:#555;margin-top:2px;">Sto. Tomas, Magarao, Camarines Sur</div>
      </div>
      <img class="seal" src="data:image/png;base64," alt="Barangay Seal" />
    </div>

    <!-- DOCUMENT TITLE -->
    <div class="doc-title-wrap">
      <div class="doc-title">${title}</div>
    </div>

    <!-- META ROW: Ref, OR, Date -->
    <div class="meta-row">
      <div class="meta-item">
        <span class="meta-label">Reference No.</span>
        <span class="meta-value">${row.ref_number}</span>
      </div>
      <div class="meta-item">
        <span class="meta-label">OR Number</span>
        <span class="meta-value">${orNum}</span>
      </div>
      <div class="meta-item" style="text-align:right;">
        <span class="meta-label">Date Issued</span>
        <span class="meta-value">${issued}</span>
      </div>
    </div>

    <!-- DOCUMENT BODY -->
    <div class="doc-body">
      ${body}
    </div>

    <!-- GIVEN THIS -->
    <div class="given">
      GIVEN THIS <u>&nbsp;${new Date(row.date_issued || new Date()).getDate()}&nbsp;</u>
      day of <u>&nbsp;${new Date(row.date_issued || new Date()).toLocaleDateString('en-PH',{month:'long'})}&nbsp;</u>,
      <u>&nbsp;${new Date(row.date_issued || new Date()).getFullYear()}&nbsp;</u>
      at Barangay Sto. Tomas, Magarao, Camarines Sur.
    </div>

    <!-- SIGNATURE -->
    <div class="signature-section">
      <div class="sig-left">
        <div style="margin-bottom:4px;font-size:10pt;color:#555;">Prepared by:</div>
        <div style="border-bottom:1px solid #000;width:180px;margin-bottom:2px;"></div>
        <div style="font-size:9.5pt;color:#444;">Barangay Secretary</div>
      </div>
      <div class="sig-right">
        <div class="sig-name">${issuedBy}</div>
        <div class="sig-title">Punong Barangay</div>
        <div style="font-size:9pt;color:#666;margin-top:2px;">Brgy. Sto. Tomas, Magarao, Cam. Sur</div>
      </div>
    </div>

    <!-- REQUESTEE -->
    <div class="requestee-section">
      <div class="requestee-box">
        <div class="requestee-name">${row.full_name}</div>
        <div class="requestee-label">Resident / Applicant</div>
      </div>
      <div style="text-align:right;font-size:9.5pt;color:#555;">
        <div>CTC No.: ________________</div>
        <div style="margin-top:4px;">Issued at: ________________</div>
        <div style="margin-top:4px;">Issued on: ________________</div>
      </div>
    </div>

    <!-- FOOTER -->
    <div class="doc-footer">
      <span>Generated by E-Sto.Tomas MIS</span>
      <span>Ref: ${row.ref_number}</span>
      <span>OR: ${orNum}</span>
    </div>

  </div><!-- border-inner -->
  </div><!-- border-outer -->

  <div class="not-valid">
    (This document is not valid without the official signature and dry seal of the Barangay.)
  </div>

</div>

<script>
  // Wait for seal images to load before printing
  const imgs = document.querySelectorAll('img');
  let loaded = 0;
  const total = imgs.length;
  function tryPrint() {
    loaded++;
    if (loaded >= total) { window.print(); window.onafterprint = () => window.close(); }
  }
  imgs.forEach(img => {
    if (img.complete) tryPrint();
    else { img.onload = tryPrint; img.onerror = tryPrint; }
  });
  if (total === 0) { window.print(); window.onafterprint = () => window.close(); }
</script>
</body>
</html>`;

  const win = window.open('', '_blank');
  win.document.write(html);
  win.document.close();
}
